package cn.zhuatech.cpq.controller; import cn.zhuatech.cpq.common.ApiResponse; import cn.zhuatech.cpq.dto.CpqDto.*; import cn.zhuatech.cpq.service.CpqService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('SALES_REP','ADMIN')") public class SalesWorkbenchController {private final CpqService service;public SalesWorkbenchController(CpqService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
